const lockPrivilegedRequests = `-- name: LockPrivilegedRequests :exec

SELECT pg_advisory_xact_lock(hashtext('privileged_actions:' || $1::text))
`

// Privileged actions (docs/specs/privileged-actions.md).
// Serialises requests of one owner, so the pending limits hold under concurrent calls.
func (q *Queries) LockPrivilegedRequests(ctx context.Context, ownerID string) error {
	_, err := q.db.Exec(ctx, lockPrivilegedRequests, ownerID)
	return err
}

const resolvePrivilegedActionCards = `-- name: ResolvePrivilegedActionCards :many
UPDATE attention_items a
SET state = 'resolved', resolved_at = now(), updated_at = now()
FROM privileged_actions p
WHERE a.owner_id = $1 AND a.source_kind = 'queue' AND a.state = 'open'
  AND a.source_id = 'privileged_action_' || p.id
  AND p.owner_id = a.owner_id AND p.state <> 'pending_approval'
RETURNING a.id
`

// Closes the open card of every action no longer waiting for the owner (expired, cancelled).
func (q *Queries) ResolvePrivilegedActionCards(ctx context.Context, ownerID string) ([]string, error) {
	rows, err := q.db.Query(ctx, resolvePrivilegedActionCards, ownerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryPrivilegedAction = `-- name: RetryPrivilegedAction :execrows
UPDATE privileged_actions
SET last_error = $1, updated_at = now(), claimed_until = NULL,
    next_attempt_at = now() + make_interval(secs => $2::double precision)
WHERE id = $3 AND state = 'executing' AND attempts = $4
`

type RetryPrivilegedActionParams struct {
	LastError    *string
	DelaySeconds float64
	ID           string
	Attempts     int32
}

// Leaves a claimed attempt for a later one, which observes before it writes.
func (q *Queries) RetryPrivilegedAction(ctx context.Context, arg RetryPrivilegedActionParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryPrivilegedAction,
		arg.LastError,
		arg.DelaySeconds,
		arg.ID,
		arg.Attempts,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settlePrivilegedDelivery = `-- name: SettlePrivilegedDelivery :execrows
UPDATE privileged_actions
SET delivery_state = $1, delivery_detail = $2, updated_at = now(),
    delivery_next_at = CASE WHEN $1::text = 'pending'
        THEN now() + make_interval(secs => $3::double precision) END
WHERE id = $4 AND delivery_state = 'pending' AND delivery_attempts = $5
`

type SettlePrivilegedDeliveryParams struct {
	DeliveryState    string
	DeliveryDetail   *string
	DelaySeconds     float64
	ID               string
	DeliveryAttempts int32
}

func (q *Queries) SettlePrivilegedDelivery(ctx context.Context, arg SettlePrivilegedDeliveryParams) (int64, error) {
	result, err := q.db.Exec(ctx, settlePrivilegedDelivery,
		arg.DeliveryState,
		arg.DeliveryDetail,
		arg.DelaySeconds,
		arg.ID,
		arg.DeliveryAttempts,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
